CREATE TABLE [dbo].[HeroSection] (
    [Id]               INT             NOT NULL,
    [BadgeText]        NVARCHAR (200)  CONSTRAINT [DF_HeroSection_BadgeText] DEFAULT (N'Prepare. Practice. Progress.') NOT NULL,
    [Title]            NVARCHAR (500)  CONSTRAINT [DF_HeroSection_Title] DEFAULT (N'Crack Government Exams & Unlock Your Dream Career') NOT NULL,
    [HighlightTitle]   NVARCHAR (200)  CONSTRAINT [DF_HeroSection_HighlightTitle] DEFAULT (N'Dream Career') NULL,
    [Description]      NVARCHAR (MAX)  CONSTRAINT [DF_HeroSection_Description] DEFAULT (N'Master competitive exams with topic-wise practice modules, instant score evaluation, daily current affairs, and real-time public sector job notifications.') NOT NULL,
    [PrimaryBtnText]   NVARCHAR (100)  CONSTRAINT [DF_HeroSection_PrimaryBtnText] DEFAULT (N'Start Free Practice') NOT NULL,
    [PrimaryBtnUrl]    NVARCHAR (200)  CONSTRAINT [DF_HeroSection_PrimaryBtnUrl] DEFAULT (N'/practice') NOT NULL,
    [SecondaryBtnText] NVARCHAR (100)  CONSTRAINT [DF_HeroSection_SecondaryBtnText] DEFAULT (N'Browse Govt Jobs') NOT NULL,
    [SecondaryBtnUrl]  NVARCHAR (200)  CONSTRAINT [DF_HeroSection_SecondaryBtnUrl] DEFAULT (N'/jobs') NOT NULL,
    [Stat1Value]       NVARCHAR (50)   CONSTRAINT [DF_HeroSection_Stat1Value] DEFAULT (N'100+') NOT NULL,
    [Stat1Label]       NVARCHAR (100)  CONSTRAINT [DF_HeroSection_Stat1Label] DEFAULT (N'Exam Categories') NOT NULL,
    [Stat2Value]       NVARCHAR (50)   CONSTRAINT [DF_HeroSection_Stat2Value] DEFAULT (N'50,000+') NOT NULL,
    [Stat2Label]       NVARCHAR (100)  CONSTRAINT [DF_HeroSection_Stat2Label] DEFAULT (N'Practice MCQs') NOT NULL,
    [Stat3Value]       NVARCHAR (50)   CONSTRAINT [DF_HeroSection_Stat3Value] DEFAULT (N'Daily') NOT NULL,
    [Stat3Label]       NVARCHAR (100)  CONSTRAINT [DF_HeroSection_Stat3Label] DEFAULT (N'Current Affairs') NOT NULL,
    [Stat4Value]       NVARCHAR (50)   CONSTRAINT [DF_HeroSection_Stat4Value] DEFAULT (N'100% Free') NOT NULL,
    [Stat4Label]       NVARCHAR (100)  CONSTRAINT [DF_HeroSection_Stat4Label] DEFAULT (N'Verified Job Alerts') NOT NULL,
    [ImageUrl]         NVARCHAR (1000) CONSTRAINT [DF_HeroSection_ImageUrl] DEFAULT (N'https://images.unsplash.com/photo-1522202176988-66273c2fd55f?q=80&w=800&auto=format&fit=crop') NOT NULL,
    [ImageTitle]       NVARCHAR (200)  CONSTRAINT [DF_HeroSection_ImageTitle] DEFAULT (N'Structured Exam Mock Tests & Instant Analytics') NOT NULL,
    [Badge1Text]       NVARCHAR (100)  CONSTRAINT [DF_HeroSection_Badge1Text] DEFAULT (N'Live Exam Alerts') NOT NULL,
    [Badge2Text]       NVARCHAR (100)  CONSTRAINT [DF_HeroSection_Badge2Text] DEFAULT (N'Instant Performance Analysis') NOT NULL,
    [IsActive]         BIT             CONSTRAINT [DF_HeroSection_IsActive] DEFAULT ((1)) NOT NULL,
    [CreatedOn]        DATETIME2 (7)   CONSTRAINT [DF_HeroSection_CreatedOn] DEFAULT (sysutcdatetime()) NOT NULL,
    [ModifiedOn]       DATETIME2 (7)   NULL,
    CONSTRAINT [PK_HeroSection] PRIMARY KEY CLUSTERED ([Id] ASC)
);

